from collections import Counter

def _runs(vals, bg):
    out=[]
    i=0
    while i<len(vals):
        j=i+1
        while j<len(vals) and vals[j]==vals[i]:
            j+=1
        if vals[i]!=bg and j-i>=2:
            out.append((i,j,vals[i]))
        i=j
    return out

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    top=_runs(g[0],bg); bottom=_runs(g[-1],bg)
    left=_runs([g[r][0] for r in range(h)],bg); right=_runs([g[r][-1] for r in range(h)],bg)

    if top and bottom and top[0][2]==bottom[0][2] and top[0][1]-top[0][0]==bottom[0][1]-bottom[0][0]:
        a,b=top[0],bottom[0]
        marks=[(r,c,g[r][c]) for r in range(1,h-1) for c in range(w)
               if g[r][c]!=bg and (a[0]<=c<a[1] or b[0]<=c<b[1])]
        for r,c,color in marks:
            if a[0]<=c<a[1]:
                mate=b[0]+c-a[0]
                g[r][c]=4
                for rr in range(r):
                    if not (rr==0 and a[0]<=c<a[1] and g[rr][c]==a[2]): g[rr][c]=color
                for rr in range(h):
                    if not (rr==h-1 and b[0]<=mate<b[1] and g[rr][mate]==b[2]): g[rr][mate]=color
            else:
                mate=a[0]+c-b[0]
                g[r][c]=4
                for rr in range(r+1,h):
                    if not (rr==h-1 and b[0]<=c<b[1] and g[rr][c]==b[2]): g[rr][c]=color
                for rr in range(h):
                    if not (rr==0 and a[0]<=mate<a[1] and g[rr][mate]==a[2]): g[rr][mate]=color
        return g

    if left and right and left[0][2]==right[0][2] and left[0][1]-left[0][0]==right[0][1]-right[0][0]:
        a,b=left[0],right[0]
        marks=[(r,c,g[r][c]) for r in range(h) for c in range(1,w-1)
               if g[r][c]!=bg and (a[0]<=r<a[1] or b[0]<=r<b[1])]
        for r,c,color in marks:
            if a[0]<=r<a[1]:
                mate=b[0]+r-a[0]
                g[r][c]=4
                for cc in range(c):
                    if not (cc==0 and a[0]<=r<a[1] and g[r][cc]==a[2]): g[r][cc]=color
                for cc in range(w):
                    if not (cc==w-1 and b[0]<=mate<b[1] and g[mate][cc]==b[2]): g[mate][cc]=color
            else:
                mate=a[0]+r-b[0]
                g[r][c]=4
                for cc in range(c+1,w):
                    if not (cc==w-1 and b[0]<=r<b[1] and g[r][cc]==b[2]): g[r][cc]=color
                for cc in range(w):
                    if not (cc==0 and a[0]<=mate<a[1] and g[mate][cc]==a[2]): g[mate][cc]=color
        return g
    return g

